style.css:
@-moz-document domain("roblox.com") {
.rbx-text-navbar-right.text-header {
    visibility: hidden;
    position: relative;
}

.rbx-text-navbar-right.text-header:after {
    visibility: visible;
    position: absolute;
    top: 0;
    left: 0;
    content: "3M+";
}

.balance-label.icon-robux-container {
    visibility: hidden;
    position: relative;
}

.balance-label.icon-robux-container:after {
    visibility: visible;
    position: absolute;
    top: 0;
    left: 0;
    content: 'My Balance: ⏣3,026,153';
}
.text-robux.ml-1.text-body-medium {
    visibility: hidden;
    position: relative;
}
.text-robux.ml-1.text-body-medium:after {
    visibility: visible;
    position: absolute;
    top: 0;
    left: -4px;
    content: "3M+";
    font-size: 90%;
    white-space: nowrap;
}
/* Buy Item modal — "balance after transaction" number only */
.rovalra-robux-after .text-robux {
    visibility: hidden;
    position: relative;
}
.rovalra-robux-after .text-robux:after {
    visibility: visible;
    position: absolute;
    top: 0;
    left: 0;
    content: "3,026,094";
    white-space: nowrap;
}

/* Robux Stipends */
table.table.summary tbody tr:nth-child(2) td.amount.icon-robux-container span.amount-display > span:last-child {
    visibility: hidden;
    position: relative;
}
table.table.summary tbody tr:nth-child(2) td.amount.icon-robux-container span.amount-display > span:last-child:after {
    visibility: visible;
    position: absolute;
    top: 0;
    left: 0;
    content: "0";
}

/* Currency Purchases */
table.table.summary tbody tr:nth-child(3) td.amount.icon-robux-container span.amount-display > span:last-child {
    visibility: hidden;
    position: relative;
}
table.table.summary tbody tr:nth-child(3) td.amount.icon-robux-container span.amount-display > span:last-child:after {
    visibility: visible;
    position: absolute;
    top: 0;
    left: 0;
    content: "0";
}

/* Sales of Goods */
table.table.summary tbody tr:nth-child(4) td.amount.icon-robux-container span.amount-display > span:last-child {
    visibility: hidden;
    position: relative;
}
table.table.summary tbody tr:nth-child(4) td.amount.icon-robux-container span.amount-display > span:last-child:after {
    visibility: visible;
    position: absolute;
    top: 0;
    left: 0;
    content: "1,492,603";
}

/* Community Payouts */
table.table.summary tbody tr:nth-child(5) td.amount.icon-robux-container span.amount-display > span:last-child {
    visibility: hidden;
    position: relative;
}
table.table.summary tbody tr:nth-child(5) td.amount.icon-robux-container span.amount-display > span:last-child:after {
    visibility: visible;
    position: absolute;
    top: 0;
    left: 0;
    content: "42,790";
}
/* Total — Incoming Robux (the font-bold row that ISN'T row 15) */
table.table.summary tbody tr:not(:nth-child(15)) td.amount.icon-robux-container.font-bold span.amount-display > span:last-child {
    visibility: hidden;
    position: relative;
}
table.table.summary tbody tr:not(:nth-child(15)) td.amount.icon-robux-container.font-bold span.amount-display > span:last-child:after {
    visibility: visible;
    position: absolute;
    top: 0;
    left: 0;
    content: "1,535,893";
}

/* Total — Outgoing Robux (row 15 specifically) */
#transactions-web-app > div > div.summary > table > tbody > tr:nth-child(15) > td.amount.icon-robux-container.font-bold span.amount-display > span:last-child {
    visibility: hidden;
    position: relative;
}
#transactions-web-app > div > div.summary > table > tbody > tr:nth-child(15) > td.amount.icon-robux-container.font-bold span.amount-display > span:last-child:after {
    visibility: visible;
    position: absolute;
    top: 0;
    left: 0;
    content: "49,721";
}
/* Pending Robux */
table.table.summary tbody tr td.amount.icon-robux-container.text-disabled span.amount-display > span:last-child {
    visibility: hidden;
    position: relative;
}
table.table.summary tbody tr td.amount.icon-robux-container.text-disabled span.amount-display > span:last-child:after {
    visibility: visible;
    position: absolute;
    top: 0;
    left: 0;
    content: "28,502";
}
/* Purchases (Outgoing) */
#transactions-web-app > div > div.summary > table > tbody > tr:nth-child(12) > td.amount.icon-robux-container > span > span:nth-child(3) {
    visibility: hidden;
    position: relative;
}
#transactions-web-app > div > div.summary > table > tbody > tr:nth-child(12) > td.amount.icon-robux-container > span > span:nth-child(3):after {
    visibility: visible;
    position: absolute;
    top: 0;
    left: 0;
    content: "49,721";
}
/* Send Robux widget balance */
#robux-redesign-page > div.flex.flex-col.items-center > div.flex.flex-col.self-stretch.medium\:self-end.medium\:margin-top-\[16px\].medium\:margin-right-\[16px\] > div > div > div.flex.flex-row.justify-center.items-center.gap-xsmall.medium\:padding-left-none > span.font-builder-extended.content-action-standard.text-title-large.\[font-size\:var\(--font-size-500\)\].medium\:\[font-size\:var\(--font-size-600\)\] {
    visibility: hidden;
    position: relative;
    display: inline-block;
    min-width: 80px;
}
#robux-redesign-page > div.flex.flex-col.items-center > div.flex.flex-col.self-stretch.medium\:self-end.medium\:margin-top-\[16px\].medium\:margin-right-\[16px\] > div > div > div.flex.flex-row.justify-center.items-center.gap-xsmall.medium\:padding-left-none > span.font-builder-extended.content-action-standard.text-title-large.\[font-size\:var\(--font-size-500\)\].medium\:\[font-size\:var\(--font-size-600\)\]:after {
    visibility: visible;
    position: absolute;
    top: 0;
    left: 0;
    content: "3,026,153";
    white-space: nowrap;
}
}
